* { box-sizing: border-box; }

body {
  margin: 0;
  color: var(--ink);
  background: var(--paper);
  font-family: "DM Sans", sans-serif;
}

button, input { font: inherit; }
button { cursor: pointer; }

.shell { min-height: 100vh; display: grid; grid-template-columns: 255px 1fr; }

.sidebar {
  position: relative;
  display: flex;
  flex-direction: column;
  padding: 34px 24px 28px;
  color: #f5f2e9;
  background: var(--green);
}

.brand {
  display: flex;
  align-items: center;
  gap: 12px;
  color: inherit;
  text-decoration: none;
  font-family: "DM Serif Display", serif;
  font-size: 25px;
  letter-spacing: .2px;
}

.brand-mark { width: 27px; height: 27px; display: grid; grid-template-columns: repeat(3, 1fr); gap: 3px; transform: rotate(-5deg); }
.brand-mark span { border-radius: 4px; background: var(--lime); }
.brand-mark span:nth-child(2) { transform: translateY(5px); background: var(--coral); }
.brand-mark span:nth-child(3) { transform: translateY(-2px); }

nav { margin-top: 65px; }
.nav-label { margin: 0 12px 12px; color: #98ada6; font-size: 11px; font-weight: 700; letter-spacing: 1.4px; text-transform: uppercase; }
.nav-item { display: flex; align-items: center; gap: 12px; padding: 12px; border-radius: 9px; color: #c7d4d0; text-decoration: none; font-size: 14px; }
.nav-item.active { color: #fff; background: rgba(255,255,255,.095); }
.nav-item svg { width: 19px; fill: none; stroke: currentColor; stroke-width: 1.7; }
.count { margin-left: auto; min-width: 22px; padding: 2px 6px; text-align: center; border-radius: 20px; color: #193c34; background: var(--lime); font-size: 11px; font-weight: 700; }

.sidebar-note { margin-top: auto; padding: 18px; border-top: 1px solid rgba(255,255,255,.13); color: #a8bbb4; font-size: 12px; line-height: 1.5; }
.sidebar-note p { margin: 6px 0 0; }
.sparkle { color: var(--lime); font-size: 18px; }

.main { min-width: 0; padding: 0 6vw 70px; }
.topbar { height: 145px; display: flex; align-items: center; justify-content: space-between; border-bottom: 1px solid var(--line); }
.eyebrow, .kicker { margin: 0 0 6px; color: var(--green-2); font-size: 11px; font-weight: 700; letter-spacing: 1.5px; text-transform: uppercase; }
.topbar h1 { margin: 0; font-family: "DM Serif Display", serif; font-size: 40px; font-weight: 400; line-height: 1; }

.primary, .secondary {
  border: 0;
  border-radius: 9px;
  padding: 13px 19px;
  font-size: 14px;
  font-weight: 600;
  transition: transform .16s ease, box-shadow .16s ease, background .16s ease;
}
.primary { color: #fff; background: var(--green); box-shadow: 0 6px 16px rgba(23,61,53,.16); }
.primary:hover { transform: translateY(-1px); background: #225346; box-shadow: 0 8px 20px rgba(23,61,53,.22); }
.primary.compact { padding: 11px 17px; }
.primary span { margin-right: 3px; font-size: 17px; }
.secondary { color: var(--ink); background: #ebe8df; }
.secondary:hover { background: #e1ddd2; }

.empty { min-height: calc(100vh - 190px); display: flex; flex-direction: column; align-items: center; justify-content: center; padding-bottom: 45px; text-align: center; }
.empty-art { position: relative; width: 260px; height: 210px; margin-bottom: 22px; }
.sun { position: absolute; top: 16px; right: 32px; width: 65px; height: 65px; border-radius: 50%; background: var(--lime); opacity: .85; }
.card { position: absolute; width: 135px; height: 150px; padding: 14px; border: 1px solid #d9d5ca; border-radius: 9px; background: #fff; box-shadow: 0 14px 30px rgba(31,48,41,.1); }
.card-back { left: 43px; top: 40px; transform: rotate(-10deg); background: #ead6ca; }
.card-front { left: 84px; top: 26px; transform: rotate(5deg); }
.picture { height: 74px; display: grid; place-items: center; margin-bottom: 14px; color: #d9e7a4; background: var(--green-2); font-size: 25px; }
.fake-line { height: 5px; margin: 7px 0; border-radius: 8px; background: #d7d4cc; }
.fake-line.title { height: 7px; width: 86%; background: #74857e; }
.fake-line.short { width: 58%; }
.leaf { position: absolute; width: 22px; height: 52px; border-radius: 90% 0 90% 0; background: var(--coral); opacity: .9; }
.leaf-one { left: 31px; bottom: 11px; transform: rotate(-28deg); }
.leaf-two { right: 30px; bottom: 22px; transform: scale(.65) rotate(21deg); background: var(--green-2); }
.empty .kicker { margin-top: 2px; }
.empty h2 { margin: 5px 0 10px; font-family: "DM Serif Display", serif; font-size: 33px; font-weight: 400; }
.empty-copy { margin: 0 0 25px; color: var(--muted); font-size: 14px; line-height: 1.65; }

.backdrop { position: fixed; inset: 0; z-index: 10; background: rgba(14,28,24,.52); backdrop-filter: blur(2px); }
.dialog { position: fixed; z-index: 11; top: 50%; left: 50%; width: min(530px, calc(100vw - 40px)); padding: 36px; transform: translate(-50%, -50%); border-radius: 15px; background: #fbfaf6; box-shadow: var(--shadow); }
.close { position: absolute; top: 18px; right: 20px; width: 34px; height: 34px; border: 0; border-radius: 50%; color: #617069; background: transparent; font-size: 25px; line-height: 1; }
.close:hover { background: #ebe8df; }
.dialog h2 { margin: 7px 35px 8px 0; font-family: "DM Serif Display", serif; font-size: 30px; font-weight: 400; }
.dialog-copy { margin: 0 0 27px; color: var(--muted); font-size: 14px; }
label { display: block; margin: 0 0 8px; font-size: 12px; font-weight: 700; }
.url-wrap { display: flex; align-items: center; gap: 10px; padding: 0 14px; border: 1px solid #cbc8bf; border-radius: 9px; background: #fff; transition: border-color .2s, box-shadow .2s; }
.url-wrap:focus-within { border-color: var(--green-2); box-shadow: 0 0 0 3px rgba(45,98,84,.12); }
.url-wrap svg { width: 19px; fill: none; stroke: #7f8984; stroke-width: 1.7; }
.url-wrap input { width: 100%; padding: 14px 0; border: 0; outline: 0; color: var(--ink); background: transparent; }
.sample-hint { margin: 12px 0 22px; color: #7b827e; font-size: 11px; line-height: 1.55; }
.sample-hint button { margin: 1px 0 0; padding: 0; border: 0; border-bottom: 1px solid #9ba59f; color: var(--green-2); background: transparent; font-size: 11px; }
.full { width: 100%; }
.full span { float: right; margin: -1px 0 0; }

.loading-step { padding: 50px 10px; text-align: center; }
.loader { height: 45px; display: flex; align-items: center; justify-content: center; gap: 7px; }
.loader span { width: 8px; height: 8px; border-radius: 50%; background: var(--green-2); animation: bounce 1s ease infinite; }
.loader span:nth-child(2) { animation-delay: .12s; }
.loader span:nth-child(3) { animation-delay: .24s; }
@keyframes bounce { 0%, 60%, 100% { transform: translateY(0); opacity: .45; } 30% { transform: translateY(-10px); opacity: 1; } }
.loading-step h2 { margin: 8px 0; }
.loading-step p { margin: 0; color: var(--muted); font-size: 13px; }

.preview { overflow: hidden; margin-top: 24px; border: 1px solid #dad7cf; border-radius: 11px; background: #fff; }
.preview-image, .bookmark-image { position: relative; display: grid; place-items: center; color: #f8f0de; background: linear-gradient(145deg, #af553f 0 32%, #e69a68 32% 47%, #244f46 47%); font-family: "DM Serif Display", serif; letter-spacing: 3px; }
.preview-image { height: 145px; }
.preview-image::after, .bookmark-image::after { content: ""; position: absolute; width: 100px; height: 100px; border: 1px solid rgba(255,255,255,.35); border-radius: 50%; }
.preview-content { padding: 18px; }
.source-line { display: flex; align-items: center; gap: 7px; color: #75807a; font-size: 11px; }
.favicon { width: 19px; height: 19px; display: grid; place-items: center; border-radius: 5px; color: white; background: #af553f; font-size: 10px; font-weight: 700; }
.preview h3 { margin: 10px 0 6px; font-family: "DM Serif Display", serif; font-size: 21px; font-weight: 400; }
.preview p { margin: 0; color: var(--muted); font-size: 12px; line-height: 1.5; }
.dialog-actions { display: flex; justify-content: flex-end; gap: 10px; margin-top: 24px; }

.library { padding-top: 38px; }
.result-count { color: var(--muted); font-size: 12px; }
.bookmark-card { width: 320px; overflow: hidden; border: 1px solid var(--line); border-radius: 12px; background: #fff; box-shadow: 0 8px 22px rgba(26,46,39,.06); }
.bookmark-image { height: 170px; }
.bookmark-body { padding: 19px; }
.bookmark-body h2 { margin: 12px 0 8px; font-family: "DM Serif Display", serif; font-size: 21px; font-weight: 400; line-height: 1.2; }
.bookmark-body p { color: var(--muted); font-size: 12px; line-height: 1.5; }
.bookmark-body .saved-line { margin: 18px 0 0; color: #96a09b; font-size: 10px; }

.toast { position: fixed; z-index: 15; right: 32px; bottom: 28px; display: flex; align-items: center; gap: 10px; padding: 13px 18px; border-radius: 9px; color: #fff; background: var(--green); box-shadow: 0 12px 35px rgba(17,45,38,.25); font-size: 13px; animation: toastIn .25s ease; }
.check { width: 21px; height: 21px; display: grid; place-items: center; border-radius: 50%; color: var(--green); background: var(--lime); font-size: 12px; font-weight: 700; }
@keyframes toastIn { from { transform: translateY(10px); opacity: 0; } }

[hidden] { display: none !important; }

@media (max-width: 760px) {
  .shell { grid-template-columns: 1fr; }
  .sidebar { display: none; }
  .main { padding: 0 24px 50px; }
  .topbar { height: 115px; }
  .topbar h1 { font-size: 33px; }
  .primary.compact { display: none; }
}

