import { mkdir, readFile, rename, writeFile } from "node:fs/promises";
import path from "node:path";

export class LibraryStore {
  constructor(filePath) {
    this.filePath = filePath;
    this.data = { version: 1, bookmarks: [] };
    this.writeQueue = Promise.resolve();
  }

  async init() {
    await mkdir(path.dirname(this.filePath), { recursive: true });
    try {
      const parsed = JSON.parse(await readFile(this.filePath, "utf8"));
      if (!Array.isArray(parsed.bookmarks)) throw new Error("Invalid library file");
      this.data = { version: 1, ...parsed };
    } catch (error) {
      if (error.code !== "ENOENT") throw error;
      await this.persist();
    }
  }

  snapshot() {
    return structuredClone(this.data);
  }

  async mutate(callback) {
    const next = structuredClone(this.data);
    const result = await callback(next);
    this.data = next;
    await this.persist();
    return result;
  }

  async persist() {
    const payload = `${JSON.stringify(this.data, null, 2)}\n`;
    const temporary = `${this.filePath}.tmp`;
    this.writeQueue = this.writeQueue.then(async () => {
      await writeFile(temporary, payload, "utf8");
      await rename(temporary, this.filePath);
    });
    return this.writeQueue;
  }
}

/work/implementation/lib/sanitize.js.content:
const ALLOWED_TAGS = new Set(["p", "br", "ul", "ol", "li", "strong", "em", "b", "i"]);

export function sanitizeNoteHtml(value) {
  let html = String(value || "")
    .replace(/<script\b[^>]*>[\s\S]*?<\/script>/gi, "")
    .replace(/<style\b[^>]*>[\s\S]*?<\/style>/gi, "")
    .replace(/<!--([\s\S]*?)-->/g, "");
  html = html.replace(/<\/?([a-z\d]+)(?:\s[^>]*)?>/gi, (whole, name) => {
    const tag = name.toLowerCase();
    if (!ALLOWED_TAGS.has(tag)) return "";
    return whole.startsWith("</") ? `</${tag}>` : tag === "br" ? "<br>" : `<${tag}>`;
  });
  return html.trim();
}

export function stripHtml(value) {
  return String(value || "")
    .replace(/<br\s*\/?>/gi, " ")
    .replace(/<\/p>|<\/li>/gi, " ")
    .replace(/<[^>]+>/g, " ")
    .replace(/&nbsp;/gi, " ")
    .replace(/&amp;/gi, "&")
    .replace(/&lt;/gi, "<")
    .replace(/&gt;/gi, ">")
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'")
    .replace(/\s+/g, " ")
    .trim();
}

